-- 036_clinic_public_page.sql
-- Public one-page website per clinic (https://inferapp.online/c/<slug>), generated by the API.
BEGIN;
ALTER TABLE emr_clinics ADD COLUMN IF NOT EXISTS slug VARCHAR(80);
ALTER TABLE emr_clinics ADD COLUMN IF NOT EXISTS public_page JSONB NOT NULL DEFAULT '{}'::jsonb;  -- tagline, about, timings, …
ALTER TABLE emr_clinics ADD COLUMN IF NOT EXISTS public_published BOOLEAN NOT NULL DEFAULT true;
CREATE UNIQUE INDEX IF NOT EXISTS uq_emr_clinics_slug ON emr_clinics (slug) WHERE slug IS NOT NULL;
COMMIT;
